 * purged issue's number stays reserved on the project, so the next value is
 * one past the highest number the project has ever used.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const db = getDb();
  const row = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const project = db
    .select({ highWater: projects.issueNumberHighWater })
    .from(projects)
    .where(
      and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)),
    )
    .get();
  return Math.max(row?.value ?? 0, project?.highWater ?? 0) + 1;
}

/**
 * Remembers `issueNumber` as issued for the project. Called before a row is
 * removed so the number cannot be allocated again.
 */
function rememberIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): void {
  const db = getDb();
  const project = db
    .select({ highWater: projects.issueNumberHighWater })
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .get();
  if (!project || project.highWater >= issueNumber) return;

  db.update(projects)
    .set({ issueNumberHighWater: issueNumber })
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .run();
}

/**
 * Permanently deletes one issue and the rows that belong to it: label links,
 * comments and attachments. The issue number is reserved first. Search
 * documents and the storage counter are the caller's to settle, using the
 * comment ids and the megabytes returned here.
 */
export async function purgeIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<{
  commentIds: readonly string[];
  storageMbReleased: number;
} | null> {
  const db = getDb();
  const issue = db
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();
  if (!issue) return null;

  rememberIssueNumber(orgId, issue.projectId as ProjectId, issue.number);

  const commentRows = db
    .select({ id: comments.id })
    .from(comments)
    .where(
      and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
    )
    .all();

  const attachmentRows = db
    .select({ sizeBytes: attachments.sizeBytes })
    .from(attachments)
    .where(
      and(
        orgPredicate(attachments.orgId, orgId),
        eq(attachments.issueId, issueId),
      ),
    )
    .all();

  const storageMbReleased = attachmentRows.reduce(
    (sum, row) => sum + Math.ceil(row.sizeBytes / BYTES_PER_MB),
    0,
  );

  db.delete(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.issueId, issueId),
      ),
    )
    .run();
  db.delete(comments)
    .where(
      and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
    )
    .run();
  db.delete(attachments)
    .where(
      and(
        orgPredicate(attachments.orgId, orgId),
        eq(attachments.issueId, issueId),
      ),
    )
    .run();
  db.delete(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .run();

  return {
    commentIds: commentRows.map((row) => row.id),
    storageMbReleased,
  };
}

