import { toIsoTimestamp } from "@/types/common";

/**
 * Soft-delete conventions.
 *
 * Archiving stamps `archived_at` rather than removing the row. Repositories
 * must express "live rows only" through these helpers so the predicate stays
 * in one place; a raw `isNull(table.archivedAt)` sprinkled through the data
 * layer is exactly the drift this module prevents. The retention sweep is the
 * one path that later deletes an expired archived issue for good.
 */

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Reasons a restore is refused after the caller has already been authorized. */
export type RestoreRefusalReason =
  | "not_archived"
  | "expired"
  | "project_archived"
  | "quota";

/**
 * Cut-off used by both restore and the retention sweep. An `archivedAt` at or
 * before this instant has had `retentionDays × 24h` pass, so it is expired.
 */
export function retentionCutoff(now: Date, retentionDays: number): IsoTimestamp {
  return toIsoTimestamp(new Date(now.getTime() - retentionDays * MS_PER_DAY));
}

export function isArchived(row: SoftDeletable): boolean {
  return row.archivedAt !== null;
}

export function isLive(row: SoftDeletable): boolean {
  return row.archivedAt === null;
}

/** Filters an in-memory collection according to an `ArchiveScope`. */
export function applyArchiveScope<T extends SoftDeletable>(
  rows: readonly T[],
  scope: ArchiveScope = {},
): readonly T[] {
  return scope.includeArchived === true ? rows : rows.filter(isLive);
}

/** True when the repository should add the `archived_at IS NULL` predicate. */
export function shouldFilterArchived(scope: ArchiveScope = {}): boolean {
  return scope.includeArchived !== true;
}
