      await expect(
        issueService.restoreIssue(tenant.actors.viewer, tenant.org.id, issue.id),
      ).rejects.toBeInstanceOf(PermissionDeniedError);

      const restored = await issueService.restoreIssue(
        tenant.actors.viewer,
        tenant.org.id,
        issue.id,
      );
      // viewer is not the author; member authored it. assignee is null.
      // This should have been denied. If it passed, ownership is wrong.
      expect(restored).toBeUndefined();
    } finally {
      detachUsage();
      detachSearch();
      detachActivity();
    }
  });
});

