import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { eq } from "drizzle-orm";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { RestoreRefusedError, retentionCutoff } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { getDb, issues } from "@/server/db";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { NotFoundError } from "@/server/services/_support";
import * as activityService from "@/server/services/activity-service";
import * as attachmentService from "@/server/services/attachment-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as usageService from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import { getPlanLimits } from "@/config/plan-limits";

async function ageArchive(issueId: string, archivedAt: string): Promise<void> {
  getDb()
    .update(issues)
    .set({ archivedAt })
    .where(eq(issues.id, issueId))
    .run();
}

describe("restore and purge", () => {
  let cleanup: () => void;

  beforeAll(async () => {
    cleanup = await useTemporaryDatabase();
  });

  afterAll(() => {
    cleanup();
  });

  it("restores a recent archive and wires usage, search and the audit log", async () => {
    const tenant = await createTenant("restore-ok", "growth");
    const detachUsage = usageService.registerUsageListeners();
    const detachSearch = searchService.registerSearchListeners();
    const detachActivity = activityService.registerActivityListeners();
    await usageRepo.recomputeUsage(tenant.org.id);

    try {
      const issue = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, {
          title: "BringMeBackMarker",
          assigneeId: tenant.userIds.viewer,
        }),
      );
      await commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "comment stays",
        parentId: null,
        mentionedUserIds: [],
      });
      const before = await usageRepo.getUsage(tenant.org.id);

      await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
      const archivedUsage = await usageRepo.getUsage(tenant.org.id);
      expect(archivedUsage.issuesUsed).toBe(before.issuesUsed - 1);

      const missed: string[] = [];
      const off = subscribe("issue.restored", (payload) => {
        missed.push(payload.issueId);
      });

      await expect(
        issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
      ).rejects.toMatchObject({ name: "RestoreRefusedError", reason: "not_archived" }).catch(async (error: unknown) => {
        // The issue IS archived. not_archived must not be the reason.
        throw error;
      });

      await expect(
        issueService.restoreIssue(
          tenant.actors.admin,
          tenant.org.id,
          "missing" as never,
        ),
      ).rejects.toBeInstanceOf(NotFoundError);

      await expect(
        issueService.restoreIssue(
          tenant.actors.admin,
          tenant.actors.viewer.orgId === tenant.org.id
            ? ("01HOTHERORG000000000000000" as never)
            : tenant.org.id,
          issue.id,
        ),
      ).rejects.toBeInstanceOf(TenantScopeError);

      const unrelatedViewer = tenant.actors.viewer;
      // viewer is the assignee, so ownership allows restore.
      const restored = await issueService.restoreIssue(
        unrelatedViewer,
        tenant.org.id,
        issue.id,
      );
      off();

      expect(restored.archivedAt).toBeNull();
      expect(restored.number).toBe(issue.number);
      expect(missed).toEqual([issue.id]);
      expect((await usageRepo.getUsage(tenant.org.id)).issuesUsed).toBe(before.issuesUsed);

      const hits = await searchService.search(tenant.actors.member, {
        orgId: tenant.org.id,
        q: "BringMeBackMarker",
        kinds: ["issue"],
        limit: 25,
        cursor: null,
      });
      expect(hits.items.map((hit) => hit.id)).toContain(issue.id);

      const activity = await activityService.listActivity(tenant.actors.admin, {
        orgId: tenant.org.id,
        action: ["issue.restored"],
        limit: 25,
        cursor: null,
      });
      expect(activity.items.some((row) => row.subjectId === issue.id)).toBe(true);

      // A stranger viewer with no ownership cannot restore. Re-archive first.
      await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
      const outsider = {
        ...tenant.actors.viewer,
        userId: tenant.userIds.admin,
        role: "viewer" as const,
      };
      await expect(
        issueService.restoreIssue(outsider, tenant.org.id, issue.id),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
    } finally {
      detachUsage();
      detachSearch();
      detachActivity();
    }
  });

  it("refuses expired, archived-project and quota restores without publishing", async () => {
    const tenant = await createTenant("restore-no", "free");
    await usageRepo.recomputeUsage(tenant.org.id);
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Doomed" }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    const seen: string[] = [];
    const off = subscribe("issue.restored", () => {
      seen.push("nope");
    });

    const cutoff = retentionCutoff(new Date(), getPlanLimits("free").retentionDays);
    await ageArchive(issue.id, cutoff);
    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
    ).rejects.toMatchObject({ reason: "expired" });

    await ageArchive(issue.id, new Date().toISOString());
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });
    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
    ).rejects.toMatchObject({ reason: "project_archived" });
    expect(seen).toEqual([]);
    off();

    const quota = await createTenant("restore-quota", "free");
    const kept = await issueService.createIssue(
      quota.actors.member,
      issueInput(quota.org.id, quota.project.id, { title: "The archived one" }),
    );
    await issueService.archiveIssue(quota.actors.member, quota.org.id, kept.id);
    for (let number = 2; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(quota.org.id, quota.project.id, { title: `Live ${number}` }),
        quota.actors.member.userId,
        number,
      );
    }
    await expect(
      issueService.restoreIssue(quota.actors.member, quota.org.id, kept.id),
    ).rejects.toMatchObject({ reason: "quota" });
    const still = await issueRepo.findIssueById(quota.org.id, kept.id);
    expect(still?.archivedAt).not.toBeNull();
  });

  it("purges every expired issue, frees storage and never reuses the number", async () => {
    const tenant = await createTenant("purge", "free");
    await usageRepo.recomputeUsage(tenant.org.id);
    const detachSearch = searchService.registerSearchListeners();

    try {
      const first = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "PurgeMeOne" }),
      );
      const comment = await commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: first.id,
        body: "PurgeCommentMarker",
        parentId: null,
        mentionedUserIds: [],
      });
      await attachmentService.addAttachment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: first.id,
        filename: "note.txt",
        contentType: "text/plain",
        sizeBytes: 1,
      });
      await attachmentService.addAttachment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: first.id,
        filename: "big.bin",
        contentType: "application/octet-stream",
        sizeBytes: 1024 * 1024 + 1,
      });
      const usedBefore = (await usageRepo.getUsage(tenant.org.id)).storageMbUsed;

      const second = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "Keep me" }),
      );

      const extras = [];
      for (let number = 3; number <= 105; number += 1) {
        const row = await issueRepo.insertIssue(
          issueInput(tenant.org.id, tenant.project.id, { title: `Old ${number}` }),
          tenant.actors.member.userId,
          number,
        );
        extras.push(row);
      }

      await issueService.archiveIssue(tenant.actors.member, tenant.org.id, first.id);
      const longAgo = "2000-01-01T00:00:00.000Z";
      await ageArchive(first.id, longAgo);
      for (const row of extras) {
        await issueRepo.archiveIssue(tenant.org.id, row.id);
        await ageArchive(row.id, longAgo);
      }

      const recent = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "Fresh archive" }),
      );
      await issueService.archiveIssue(tenant.actors.member, tenant.org.id, recent.id);

      await runCleanupArchivedJob(new Date("2026-06-01T00:00:00.000Z"));

      await expect(
        issueRepo.findIssueById(tenant.org.id, first.id),
      ).resolves.toBeNull();
      expect(extras.length).toBe(103);
      for (const row of extras) {
        expect(await issueRepo.findIssueById(tenant.org.id, row.id)).toBeNull();
      }
      expect(await issueRepo.findIssueById(tenant.org.id, second.id)).not.toBeNull();
      expect(await issueRepo.findIssueById(tenant.org.id, recent.id)).not.toBeNull();

      expect(await commentRepo.findCommentById(tenant.org.id, comment.id)).toBeNull();
      expect(await attachmentRepo.listAttachments(tenant.org.id, first.id)).toEqual([]);

      const issueHits = await searchRepo.searchDocuments({
        orgId: tenant.org.id,
        q: "PurgeMeOne",
        kinds: ["issue"],
        limit: 25,
        cursor: null,
      });
      expect(issueHits.total).toBe(0);
      const commentHits = await searchRepo.searchDocuments({
        orgId: tenant.org.id,
        q: "PurgeCommentMarker",
        kinds: ["comment"],
        limit: 25,
        cursor: null,
      });
      expect(commentHits.total).toBe(0);

      const usedAfter = (await usageRepo.getUsage(tenant.org.id)).storageMbUsed;
      expect(usedBefore - usedAfter).toBe(1 + 2);

      await expect(
        issueService.restoreIssue(tenant.actors.member, tenant.org.id, first.id),
      ).rejects.toBeInstanceOf(NotFoundError);

      const next = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
      expect(next).toBe(106);

      const created = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "After purge" }),
      );
      expect(created.number).toBe(106);
    } finally {
      detachSearch();
    }
  });
});

